def gameDir = rootProject.file('../game')
def allowIncompleteGame = (findProperty('wishweave.allowIncompleteGame') ?: 'false').toString() == 'true'

def bundleGame = tasks.register('bundleGame', Sync) {
    group = 'wishweave'
    description = 'Copies ../game into generated Android assets under game/.'
    into layout.buildDirectory.dir('generated/gameAssets')
    from(gameDir) {
        into 'game'
        // Dev/test-only and editor files are not shipped.
        exclude '**/.DS_Store', '**/Thumbs.db', '**/desktop.ini', '**/*.md', '**/*.map',
                '**/node_modules/**', '**/__pycache__/**', '**/tests/**',
                '**/*.test.js', '**/*.spec.js', '**/*.orig', '**/*.swp', '**/*~'
    }
    doFirst {
        if (!new File(gameDir, 'index.html').isFile()) {
            def message = "Missing ${gameDir}/index.html: the game entry page is not there yet."
            if (allowIncompleteGame) {
                logger.warn("WARNING: ${message} Building anyway (-Pwishweave.allowIncompleteGame=true).")
            } else {
                throw new GradleException(message +
                    ' Build after game/ is complete, or pass -Pwishweave.allowIncompleteGame=true for a host-only test build.')
            }
        }
    }
}
